-- 0047_aws_rds_cloudwatch_cloudtrail.sql
-- Bổ sung các bài học và lab chuyên sâu về Amazon RDS, CloudWatch và CloudTrail:
-- 1. Hai decks mới: 'database' (Amazon RDS & Databases) và 'observability' (CloudWatch & CloudTrail).
-- 2. Bộ thẻ Concept đầy đủ về RDS (Subnet Groups, Multi-AZ, Read Replica, KMS, Snapshot),
--    CloudWatch (Metrics, Log Groups, Agent RAM/Disk, Metric Filters, Alarms),
--    và CloudTrail (Audit Trail, Multi-Region, Log File Integrity, S3 Protection).
-- 3. 6 câu hỏi thực hành trắc nghiệm chuyên sâu (MCQ) trong deck 'practice'.
-- 4. 3 bài Lab thực hành tương tác chuyên nghiệp:
--    - Lab AWS-9: RDS PostgreSQL trong VPC (Subnet Group, Multi-AZ, Security Group & KMS)
--    - Lab AWS-10: CloudWatch (Cài Agent, gom log, Metric Filter & tạo Alarm)
--    - Lab AWS-11: CloudTrail (Multi-Region Trail, Log File Integrity & S3 Encryption)

-- 1. Thêm 2 decks mới vào subject AWS
INSERT INTO decks (subject_id, slug, name, description, default_kind, sort_order)
SELECT s.id, d.slug, d.name, d.description, d.kind, d.sort_order
FROM (VALUES
  ('database', 'Amazon RDS & Databases', 'RDS PostgreSQL/MySQL, Subnet Groups, Multi-AZ, Read Replicas, backup & KMS', 'concept', 4),
  ('observability', 'CloudWatch & CloudTrail', 'Monitoring, Metrics, Log Groups, Alarms, Agent, API audit trails, Log Integrity', 'concept', 7)
) AS d(slug, name, description, kind, sort_order)
JOIN subjects s ON s.slug = 'aws'
ON CONFLICT (subject_id, slug) DO UPDATE
SET name = EXCLUDED.name, description = EXCLUDED.description;

-- 2. Thêm concept cards cho RDS
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'concept', c.front, c.payload, 'seed'
FROM (VALUES
  ('Amazon RDS tổng quan', '{"back": "Fully-managed relational database service supporting PostgreSQL, MySQL, MariaDB, Oracle, SQL Server. AWS manages OS patching, automated backups, and failure recovery.", "note_vi": "Dịch vụ CSDL quan hệ được AWS quản lý toàn diện (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server). AWS lo vá lỗi hệ điều hành, backup định kỳ, sao lưu và tự hồi phục khi node lỗi.", "example": "aws rds create-db-instance --db-instance-identifier mydb ..."}'::jsonb),
  ('RDS DB Subnet Group', '{"back": "A collection of subnets (must span at least TWO Availability Zones) designated for RDS DB instances in a VPC. Best practice: use private subnets only.", "note_vi": "Tập hợp tối thiểu 2 subnet nằm ở 2 Availability Zone (AZ) khác nhau trong cùng 1 VPC dành cho RDS. Luôn luôn dùng private subnets trong production, không bao giờ để database public.", "example": "aws rds create-db-subnet-group --db-subnet-group-name app-db-subnets --subnet-ids subnet-1 subnet-2"}'::jsonb),
  ('RDS Multi-AZ Deployment', '{"back": "Synchronous replication to a standby instance in a different AZ for High Availability and automatic failover - does NOT increase read performance.", "note_vi": "Cơ chế High Availability (sẵn sàng cao): đồng bộ dữ liệu (synchronous) sang 1 instance dự phòng (standby) ở AZ khác. Tự động failover trong 60-120s khi node chính chết. Standby KHÔNG phục vụ truy vấn đọc (không tăng hiệu năng read).", "example": "aws rds modify-db-instance --db-instance-identifier mydb --multi-az --apply-immediately"}'::jsonb),
  ('RDS Read Replica', '{"back": "Asynchronous replication to one or more read-only instances for read scaling (can span across regions or be in the same region). Can be promoted to standalone DB.", "note_vi": "Nhân bản bất đồng bộ (asynchronous) sang 1 hoặc nhiều instance chỉ-đọc để giảm tải SELECT cho node chính. Có thể nằm cùng AZ, khác AZ hoặc khác Region. Có thể tách thành database độc lập khi cần.", "example": "aws rds create-db-instance-read-replica --db-instance-identifier mydb-replica --source-db-instance-identifier mydb"}'::jsonb),
  ('RDS Automated Backup & Manual Snapshot', '{"back": "Automated backups take daily full backups + continuous transaction logs (1-35 days retention, Point-In-Time Restore to any second). Snapshots are manual, persist until you delete them.", "note_vi": "Automated Backup: AWS tự backup full hàng ngày + lưu transaction logs liên tục (giữ từ 1-35 ngày), cho phép phục hồi về bất kỳ giây nào (Point-In-Time Restore). Manual Snapshot: chụp thủ công, tồn tại vĩnh viễn cho đến khi bạn tự tay xóa.", "example": "aws rds create-db-snapshot --db-instance-identifier mydb --db-snapshot-identifier mydb-snap-2026"}'::jsonb),
  ('RDS Security: Private Subnet + Security Group + KMS', '{"back": "Best practice: DB instance in private subnets with PubliclyAccessible=false, port (5432/3306) restricted to app Security Group only, storage encrypted with AWS KMS.", "note_vi": "Chuẩn bảo mật RDS: PubliclyAccessible=false, nằm trong private subnet, Security Group chỉ nhận inbound port 5432/3306 từ Security Group của app backend (không theo IP), và mã hóa storage bằng KMS key riêng.", "example": "aws ec2 authorize-security-group-ingress --group-id sg-db --protocol tcp --port 5432 --source-group sg-app"}'::jsonb),
  ('RDS Parameter Group & Option Group', '{"back": "Parameter Group controls database engine configuration parameters (like max_connections, work_mem, timezone). Option Group enables extra features (e.g. SSL, auditing extensions).", "note_vi": "Parameter Group quản lý các tham số cấu hình của DB engine (như max_connections, work_mem, timezone, logging). Option Group kích hoạt tính năng mở rộng của engine (như SSL, audit plugin).", "example": "aws rds modify-db-parameter-group --db-parameter-group-name custom-pg --parameters \"ParameterName=rds.force_ssl,ParameterValue=1,ApplyMethod=immediate\""}'::jsonb)
) AS c(front, payload)
JOIN decks d ON d.slug = 'database' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT (deck_id, kind, lower(front)) DO NOTHING;

-- 3. Thêm concept cards cho Observability (CloudWatch & CloudTrail)
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'concept', c.front, c.payload, 'seed'
FROM (VALUES
  ('CloudWatch Metrics & Namespaces', '{"back": "Time-series performance data published by AWS services (e.g., AWS/EC2: CPUUtilization) or custom metrics. Fundamental building block for monitoring and alarms.", "note_vi": "Dữ liệu chuỗi thời gian (time-series) do dịch vụ AWS hoặc custom script đẩy lên (vd namespace AWS/EC2 có metric CPUUtilization, NetworkIn). Chu kỳ mặc định 5 phút (Basic) hoặc 1 phút (Detailed Monitoring).", "example": "aws cloudwatch get-metric-data ..."}'::jsonb),
  ('CloudWatch Logs: Log Group & Log Stream', '{"back": "Log Group = collection of log streams with shared retention/IAM policies (e.g. /aws/ec2/app). Log Stream = sequence of log events from the same source (e.g. instance-id).", "note_vi": "Log Group: tập hợp các log stream có chung thời gian lưu trữ (retention policy), phân quyền IAM và Metric Filter (vd: /aws/ec2/production-app). Log Stream: chuỗi các sự kiện log thực tế phát sinh từ 1 nguồn cụ thể (vd: 1 container hoặc 1 EC2 instance).", "example": "aws logs create-log-group --log-group-name /apps/payment-service"}'::jsonb),
  ('CloudWatch Agent trên EC2 (RAM & Disk Metrics)', '{"back": "Hypervisor monitors CPU, network, disk I/O, but CANNOT see inside the OS. CloudWatch Agent must be installed to monitor Memory (RAM) and Disk space usage.", "note_vi": "Hypervisor của AWS chỉ nhìn thấy CPU, Network và Disk I/O từ bên ngoài, KHÔNG THỂ nhìn thấy RAM và dung lượng ổ cứng (Disk space) bên trong OS. Bắt buộc phải cài CloudWatch Agent bên trong EC2 để thu thập RAM và Disk.", "example": "sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a fetch-config -m ec2 -s -c file:/opt/aws/amazon-cloudwatch-agent/bin/config.json"}'::jsonb),
  ('CloudWatch Metric Filter', '{"back": "Extracts numerical metrics from text log patterns in Log Groups (e.g., counting occurrences of \"ERROR\" or \"500 Internal Server Error\") to trigger alarms.", "note_vi": "Quét log text trong Log Group theo cú pháp pattern (ví dụ đếm số lần xuất hiện chữ ERROR hoặc mã 500), biến kết quả tìm kiếm thành một CloudWatch Metric số học để có thể gắn Alarm cảnh báo.", "example": "aws logs put-metric-filter --log-group-name /apps/payment --filter-name ErrorCount --filter-pattern \"ERROR\" --metric-transformations metricName=AppErrorCount,metricNamespace=CustomApp,metricValue=1"}'::jsonb),
  ('CloudWatch Alarms & Actions', '{"back": "Watches a single metric over specified periods. When threshold is breached, performs actions: SNS notification, Auto Scaling action, or EC2 recovery.", "note_vi": "Theo dõi 1 metric trong khoảng thời gian xác định. Khi vượt ngưỡng (threshold) sẽ kích hoạt Action: gửi thông báo qua Amazon SNS (email/SMS/Slack webhook), kích hoạt Auto Scaling scale-out/scale-in, hoặc reboot/recover EC2.", "example": "aws cloudwatch put-metric-alarm --alarm-name HighCPU --metric-name CPUUtilization --namespace AWS/EC2 --statistic Average --period 300 --threshold 80 --comparison-operator GreaterThanThreshold --alarm-actions arn:aws:sns:..."}'::jsonb),
  ('CloudTrail tổng quan & Audit Trail', '{"back": "Records every API activity and console login across your AWS account (who called what API, when, from which IP, request parameters, response). Essential for PCI-DSS & SOC 2 compliance.", "note_vi": "Ghi lại toàn bộ lịch sử gọi API và đăng nhập Console trong tài khoản AWS (ai gọi, lệnh gì, lúc mấy giờ, từ địa chỉ IP nào, tham số gì). Bằng chứng kiểm toán bắt buộc của PCI-DSS, SOC 2, ISO 27001.", "example": "aws cloudtrail lookup-events --lookup-attributes AttributeKey=EventName,AttributeValue=AuthorizeSecurityGroupIngress"}'::jsonb),
  ('Multi-Region Trail vs Single-Region Trail', '{"back": "Best practice: always create a Multi-Region Trail. It captures API activity across all AWS regions (including regions you don''t actively use, catching unauthorized activity).", "note_vi": "Luôn tạo Multi-Region Trail (--is-multi-region-trail). Nó ghi lại API activity trên TOÀN BỘ các region của AWS, bao gồm cả những region bạn không dùng - giúp phát hiện ngay kẻ tấn công tạo máy đào coin hoặc mở tài nguyên ở region lạ.", "example": "aws cloudtrail create-trail --name global-audit-trail --s3-bucket-name audit-bucket --is-multi-region-trail"}'::jsonb),
  ('CloudTrail: Management Events vs Data Events', '{"back": "Management Events (enabled by default) = control plane actions (create EC2, delete bucket, modify IAM). Data Events (optional, high-volume) = data plane actions (S3 GetObject/PutObject, Lambda invocations).", "note_vi": "Management Events (mặc định bật): ghi thao tác quản trị hạ tầng (tạo EC2, xóa S3 bucket, sửa IAM role). Data Events (tùy chọn, tính phí theo lượng request): ghi thao tác trên dữ liệu (S3 GetObject/PutObject, chạy hàm Lambda).", "example": "aws cloudtrail put-event-selectors --trail-name global-audit-trail --data-resources ..."}'::jsonb),
  ('CloudTrail Log File Integrity Validation', '{"back": "Uses SHA-256 cryptographic hashes and digital signatures to ensure CloudTrail log files in S3 have not been modified, deleted, or tampered with since creation.", "note_vi": "Cơ chế xác thực tính toàn vẹn file log: AWS tự động tạo mã băm SHA-256 và chữ ký số (digest file) mỗi giờ. Cho phép kiểm toán viên chứng minh file log trong S3 chưa từng bị sửa đổi hay xóa sau khi ghi.", "example": "aws cloudtrail update-trail --name global-audit-trail --enable-log-file-validation"}'::jsonb),
  ('Bảo mật S3 Bucket lưu CloudTrail Log', '{"back": "Bucket storing CloudTrail logs must have S3 Block Public Access enabled, MFA Delete/Object Lock or versioning, SSE-KMS encryption, and bucket policy preventing deletion.", "note_vi": "Bucket S3 lưu log CloudTrail là mục tiêu đầu tiên hacker tìm cách xóa để xóa dấu vết: bắt buộc bật S3 Block Public Access, SSE-KMS với key riêng, Versioning (hoặc Object Lock WORM), và Bucket Policy cấm hành động s3:Delete*.", "example": "aws s3api put-bucket-encryption --bucket trail-bucket --server-side-encryption-configuration ..."}'::jsonb)
) AS c(front, payload)
JOIN decks d ON d.slug = 'observability' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT (deck_id, kind, lower(front)) DO NOTHING;

-- 4. Thêm câu hỏi thực hành MCQ về RDS, CloudWatch & CloudTrail vào deck 'practice'
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'mcq', q.front, q.payload, 'seed'
FROM (VALUES
  ('What is the primary architectural difference between RDS Multi-AZ and an RDS Read Replica?', '{"choices": ["Multi-AZ provides High Availability with synchronous replication to an inactive standby; Read Replicas provide read scalability with asynchronous replication", "Multi-AZ increases SELECT performance, whereas Read Replicas are only for disaster recovery", "Read Replicas replicate synchronously across regions; Multi-AZ is asynchronous within one AZ", "There is no difference - both can take read/write traffic equally"], "answer": 0, "explanation": "Multi-AZ is designed purely for High Availability and automatic failover: data is synchronously replicated to a standby node that does NOT accept traffic. Read Replicas accept read queries asynchronously to scale read workloads."}'::jsonb),
  ('What is a mandatory requirement when creating an RDS DB Subnet Group in a VPC?', '{"choices": ["It must contain subnets in at least two different Availability Zones", "It must include at least one public subnet with an Internet Gateway route", "All subnets must use the /16 CIDR block size", "It must be associated directly with an IAM instance profile"], "answer": 0, "explanation": "AWS requires an RDS DB Subnet Group to span at least two Availability Zones in the chosen region so that RDS can place standby instances or failover targets in a separate AZ."}'::jsonb),
  ('A system administrator notices that standard Amazon CloudWatch metrics for an EC2 instance show CPU and network usage, but NOT memory (RAM) or disk space utilization. Why?', '{"choices": ["RAM and disk space are internal operating system metrics that the AWS hypervisor cannot inspect without the CloudWatch Agent installed inside the OS", "Detailed Monitoring must be enabled on the EC2 instance for an extra fee", "The EC2 instance type does not support memory reporting", "CloudWatch only supports memory metrics for Windows instances"], "answer": 0, "explanation": "The hypervisor only sees external hardware metrics (CPU, disk I/O, network). OS-internal metrics like memory (RAM) and filesystem disk utilization require an agent (CloudWatch Agent) running inside the guest operating system."}'::jsonb),
  ('How can you configure CloudWatch to trigger an alert when an application log file contains more than 10 "500 Internal Server Error" occurrences in 5 minutes?', '{"choices": ["Create a Metric Filter on the CloudWatch Log Group to transform log text occurrences into a numerical metric, then attach a CloudWatch Alarm to that metric", "CloudWatch cannot parse text logs; you must export all logs to Amazon S3 and query them with Athena first", "Configure an EC2 health check rule in Route 53", "Use an IAM policy attached to the Log Group to send an SNS notification directly"], "answer": 0, "explanation": "A CloudWatch Metric Filter scans incoming log streams for patterns (e.g. [..., status=5*, ...]) and increments a custom numerical metric, which a standard CloudWatch Alarm can evaluate and alert on."}'::jsonb),
  ('Why is it a security best practice to configure AWS CloudTrail as a Multi-Region Trail rather than a Single-Region Trail?', '{"choices": ["It captures API activity in all AWS regions, detecting unexpected or malicious activity even in regions your company does not actively operate in", "Single-region trails do not support S3 storage", "Multi-region trails are required to log EC2 user data scripts", "AWS disables CloudTrail automatically after 30 days if it is not multi-region"], "answer": 0, "explanation": "Attackers who obtain compromised credentials often spin up expensive resources (e.g. crypto miners) in unused foreign regions. A Multi-Region Trail ensures every API call across all AWS regions is captured."}'::jsonb),
  ('What cryptographic capability does CloudTrail Log File Integrity Validation provide to auditors (e.g., for PCI-DSS or SOC 2)?', '{"choices": ["It generates hourly SHA-256 digest files with digital signatures so auditors can mathematically verify that logs have not been modified or deleted", "It encrypts the log files with a one-time pad that AWS cannot read", "It permanently disables the ability to delete the entire AWS account", "It stores a duplicate copy of logs on physical tape drives in an AWS bunker"], "answer": 0, "explanation": "When enabled, CloudTrail delivers hourly digest files containing SHA-256 hashes of the log files. Using the AWS CLI command ''aws cloudtrail validate-logs'', auditors can verify that log files were not modified, deleted, or forged."}'::jsonb)
) AS q(front, payload)
JOIN decks d ON d.slug = 'practice' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT (deck_id, kind, lower(front)) DO NOTHING;

-- 5. Thêm 3 bài Lab mới (Lab AWS-9, AWS-10, AWS-11) vào deck 'labs'
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', l.front, l.payload, 'seed'
FROM (VALUES
  ('Lab AWS-9 - RDS PostgreSQL: Subnet Group, Multi-AZ, Security Group & KMS', '{"scenario": "Hệ thống cần 1 database PostgreSQL 16 quản lý dữ liệu đơn hàng. Yêu cầu: nằm hoàn toàn trong private subnet (2 AZ), kích hoạt Multi-AZ để dự phòng, mã hóa bằng AWS KMS, và Security Group chỉ nhận kết nối cổng 5432 từ app backend sg-0dddddddddddddddd.", "difficulty": "trung_binh", "steps": [{"prompt": "Tạo DB Subnet Group tên app-db-subnets gồm 2 private subnet subnet-0aaaaaaaaaaaaaaaa và subnet-0bbbbbbbbbbbbbbbb.", "type": "command", "hint": "aws rds create-db-subnet-group --db-subnet-group-name app-db-subnets --db-subnet-group-description \"App DB Subnets\" --subnet-ids subnet-0aaaaaaaaaaaaaaaa subnet-0bbbbbbbbbbbbbbbb", "patterns": ["aws\\s+rds\\s+create-db-subnet-group(?=.*--db-subnet-group-name\\s+app-db-subnets)(?=.*subnet-0aaaaaaaaaaaaaaaa)(?=.*subnet-0bbbbbbbbbbbbbbbb).*"], "explanation": "RDS DB Subnet Group bắt buộc phải chứa subnet ở tối thiểu 2 Availability Zone (AZ) khác nhau, đảm bảo sẵn sàng khi kích hoạt Multi-AZ."}, {"prompt": "Tạo Security Group sg-0eeeeeeeeeeeeeeee tên rds-pg-sg cho database trong VPC vpc-0abc123456789de01.", "type": "command", "hint": "aws ec2 create-security-group --group-name rds-pg-sg --description \"RDS PostgreSQL SG\" --vpc-id vpc-0abc123456789de01", "patterns": ["aws\\s+ec2\\s+create-security-group(?=.*--group-name\\s+rds-pg-sg)(?=.*--vpc-id\\s+vpc-0abc123456789de01).*"], "explanation": "Tạo Security Group chuyên biệt cho Database layer, tách biệt hoàn toàn với Security Group của Web/App layer."}, {"prompt": "Mở cổng 5432 trên Security Group sg-0eeeeeeeeeeeeeeee, CHỈ cho phép traffic từ Security Group của app backend (sg-0dddddddddddddddd) - không mở cho bất kỳ IP CIDR nào.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 5432 --source-group sg-0dddddddddddddddd", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+5432)(?=.*--source-group\\s+sg-0dddddddddddddddd).*"], "explanation": "--source-group đảm bảo chỉ các máy tính/container mang đúng security group của app mới kết nối được, an toàn tuyệt đối trước việc thay đổi IP nội bộ."}, {"prompt": "Khởi tạo RDS PostgreSQL instance tên orders-db: engine postgres 16.1, class db.t4g.micro, storage 20GB gp3, bật Multi-AZ, mã hóa KMS với key alias/db-key, subnet group app-db-subnets, security group sg-0eeeeeeeeeeeeeeee, không public.", "type": "command", "hint": "aws rds create-db-instance --db-instance-identifier orders-db --db-instance-class db.t4g.micro --engine postgres --engine-version 16.1 --allocated-storage 20 --storage-type gp3 --multi-az --storage-encrypted --kms-key-id alias/db-key --db-subnet-group-name app-db-subnets --vpc-security-group-ids sg-0eeeeeeeeeeeeeeee --no-publicly-accessible --master-username dbadmin --master-user-password \"SecretPassword123!\"", "patterns": ["aws\\s+rds\\s+create-db-instance(?=.*--db-instance-identifier\\s+orders-db)(?=.*--db-instance-class\\s+db\\.t4g\\.micro)(?=.*--engine\\s+postgres)(?=.*--multi-az)(?=.*--storage-encrypted)(?=.*--no-publicly-accessible).*"], "explanation": "Cấu hình chuẩn production: --multi-az bảo vệ tính sẵn sàng, --storage-encrypted mã hóa dữ liệu tại chỗ, --no-publicly-accessible triệt tiêu rủi ro lộ DB ra ngoài Internet."}, {"prompt": "Tạo 1 bản Snapshot thủ công của database orders-db với tên orders-db-pre-migration-snap trước khi thực hiện bảo trì hệ thống.", "type": "command", "hint": "aws rds create-db-snapshot --db-instance-identifier orders-db --db-snapshot-identifier orders-db-pre-migration-snap", "patterns": ["aws\\s+rds\\s+create-db-snapshot(?=.*--db-instance-identifier\\s+orders-db)(?=.*--db-snapshot-identifier\\s+orders-db-pre-migration-snap).*"], "explanation": "Snapshot thủ công không bị tự động xóa khi DB instance bị xóa (khác với automated backup), là chốt chặn an toàn nhất trước các đợt release lớn."}], "reference": "## Amazon RDS: Subnet Group, Multi-AZ, Security Group & KMS Encryption\n\n**1. DB Subnet Group:**\n- Bắt buộc phải chứa subnet thuộc ít nhất **2 Availability Zone (AZ)** khác nhau trong cùng 1 VPC.\n- Luôn chỉ định **private subnets**, không bao giờ đưa public subnet vào DB Subnet Group.\n\n**2. Multi-AZ vs Read Replica:**\n- **Multi-AZ:** Đồng bộ đồng thời (Synchronous replication) sang 1 standby instance ở AZ khác. Mục đích: **High Availability & Tự động failover** (60-120 giây). Node standby **không nhận query SELECT** (không tăng hiệu năng đọc).\n- **Read Replica:** Đồng bộ bất đồng bộ (Asynchronous replication) sang các node chỉ-đọc. Mục đích: **Tăng tải truy vấn SELECT (Read scalability)**.\n\n**3. Bảo mật Database chuẩn Enterprise & PCI-DSS:**\n- `--no-publicly-accessible`: Đảm bảo không cấp public IP.\n- Security Group ingress: **CHỈ dùng `--source-group <sg-của-backend>`**, cấm tuyệt đối `--cidr 0.0.0.0/0`.\n- `--storage-encrypted --kms-key-id <key-alias>`: Mã hóa ổ đĩa lưu trữ, log, snapshot và replica bằng AWS KMS CMK."}'::jsonb),
  ('Lab AWS-10 - CloudWatch: Cài CloudWatch Agent, gom log, Metric Filter & tạo Alarm', '{"scenario": "EC2 app-server đang chạy. Hypervisor mặc định không theo dõi được RAM và log ứng dụng. Bạn cần tạo Log Group, cài/chạy CloudWatch Agent để thu thập log file /var/log/app.log, tạo Metric Filter đếm lỗi 5xx và thiết lập CloudWatch Alarm gửi cảnh báo khi có quá 5 lỗi trong 1 phút.", "difficulty": "trung_binh", "steps": [{"prompt": "Tạo 1 CloudWatch Log Group tên /aws/ec2/production-app để lưu trữ log tập trung từ các máy chủ.", "type": "command", "hint": "aws logs create-log-group --log-group-name /aws/ec2/production-app", "patterns": ["aws\\s+logs\\s+create-log-group\\s+--log-group-name\\s+/aws/ec2/production-app"], "explanation": "create-log-group tạo nơi chứa log logic, nơi các stream log của các máy con đổ về."}, {"prompt": "Đặt retention policy (thời gian lưu trữ) 30 ngày cho Log Group /aws/ec2/production-app để tối ưu chi phí lưu trữ.", "type": "command", "hint": "aws logs put-retention-policy --log-group-name /aws/ec2/production-app --retention-in-days 30", "patterns": ["aws\\s+logs\\s+put-retention-policy(?=.*--log-group-name\\s+/aws/ec2/production-app)(?=.*--retention-in-days\\s+30).*"], "explanation": "Mặc định CloudWatch Log Group giữ log Never Expire (vĩnh viễn). Luôn đặt retention policy phù hợp với yêu cầu lưu trữ và ngân sách."}, {"prompt": "Khởi động CloudWatch Agent trên máy Linux bằng lệnh amazon-cloudwatch-agent-ctl, tải cấu hình từ file /opt/aws/amazon-cloudwatch-agent/bin/config.json.", "type": "command", "hint": "sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a fetch-config -m ec2 -s -c file:/opt/aws/amazon-cloudwatch-agent/bin/config.json", "patterns": ["sudo\\s+/opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl(?=.*-a\\s+fetch-config)(?=.*-m\\s+ec2)(?=.*-s)(?=.*-c\\s+file:/opt/aws/amazon-cloudwatch-agent/bin/config\\.json).*"], "explanation": "-a fetch-config nạp cấu hình mới, -s khởi động agent daemon ngay lập tức để đẩy RAM/Disk metrics và log files lên CloudWatch."}, {"prompt": "Tạo Metric Filter tên Http5xxErrors trên Log Group /aws/ec2/production-app để lọc pattern \"[..., status=5*, ...]\" và đẩy giá trị 1 vào metric Http5xxCount trong namespace CustomApp.", "type": "command", "hint": "aws logs put-metric-filter --log-group-name /aws/ec2/production-app --filter-name Http5xxErrors --filter-pattern \"[..., status=5*, ...]\" --metric-transformations metricName=Http5xxCount,metricNamespace=CustomApp,metricValue=1", "patterns": ["aws\\s+logs\\s+put-metric-filter(?=.*--log-group-name\\s+/aws/ec2/production-app)(?=.*--filter-name\\s+Http5xxErrors)(?=.*metricName=Http5xxCount)(?=.*metricNamespace=CustomApp).*"], "explanation": "put-metric-filter trích xuất dữ liệu từ log dạng text thành metric số học có thể biểu diễn trên biểu đồ và gắn Alarm."}, {"prompt": "Tạo CloudWatch Alarm tên HighHttp5xxAlert: giám sát metric Http5xxCount trong namespace CustomApp, chu kỳ 60s, kích hoạt khi tổng (Sum) >= 5, gửi cảnh báo qua SNS topic arn:aws:sns:ap-southeast-1:123456789012:ops-alerts.", "type": "command", "hint": "aws cloudwatch put-metric-alarm --alarm-name HighHttp5xxAlert --metric-name Http5xxCount --namespace CustomApp --statistic Sum --period 60 --threshold 5 --comparison-operator GreaterThanOrEqualToThreshold --alarm-actions arn:aws:sns:ap-southeast-1:123456789012:ops-alerts --evaluation-periods 1", "patterns": ["aws\\s+cloudwatch\\s+put-metric-alarm(?=.*--alarm-name\\s+HighHttp5xxAlert)(?=.*--metric-name\\s+Http5xxCount)(?=.*--namespace\\s+CustomApp)(?=.*--threshold\\s+5)(?=.*GreaterThanOrEqualToThreshold).*"], "explanation": "put-metric-alarm thiết lập ngưỡng cảnh báo tự động; khi điều kiện vi phạm xảy ra trong thời gian đánh giá (evaluation periods), action SNS sẽ bắn thông báo tới đội ngũ trực ban."}], "reference": "## AWS CloudWatch: Agent, Logs, Metric Filters & Alarms\n\n**1. Hypervisor vs CloudWatch Agent:**\n- **Hypervisor:** Tự động thu thập CPUUtilization, NetworkIn/NetworkOut, DiskReadOps/DiskWriteBytes (chu kỳ 5 phút hoặc 1 phút).\n- **CloudWatch Agent:** Bắt buộc phải cài bên trong OS nếu muốn theo dõi: **Memory % (RAM)**, **Disk space used % (dung lượng ổ cứng)**, và **gom log files (/var/log/...)**.\n\n**2. Quản lý CloudWatch Logs:**\n- Luôn đặt **Retention Period** (`put-retention-policy`) thay vì để mặc định \"Never Expire\" để tránh chi phí phình to theo thời gian.\n- Dùng **Metric Filter** để biến các dòng log lỗi (\"ERROR\", \"status=500\") thành số đếm (Counter metric) theo thời gian thực.\n\n**3. CloudWatch Alarm & Actions:**\n- Alarm có 3 trạng thái: `OK`, `ALARM`, `INSUFFICIENT_DATA`.\n- Action phổ biến: gửi message vào **Amazon SNS** (tích hợp Slack/PagerDuty/Email), kích hoạt **EC2 Auto Scaling Action** (thêm/bớt node), hoặc tự động **Reboot/Recover EC2** khi instance bị treo."}'::jsonb),
  ('Lab AWS-11 - CloudTrail: Multi-Region Trail, Log File Integrity & S3 Encryption', '{"scenario": "Để đáp ứng yêu cầu kiểm toán SOC 2 & PCI-DSS, công ty cần triển khai CloudTrail trên toàn bộ Region (Multi-Region Trail), lưu trữ log vào bucket S3 bảo mật có mã hóa SSE-KMS, bật tính năng chống sửa đổi log (Log File Integrity Validation) và bật ghi nhận CloudTrail Insights để phát hiện bất thường API.", "difficulty": "nang_cao", "steps": [{"prompt": "Tạo Multi-Region CloudTrail tên company-audit-trail lưu vào bucket S3 company-audit-logs-2026, chỉ định KMS key alias/audit-kms-key để mã hóa log file.", "type": "command", "hint": "aws cloudtrail create-trail --name company-audit-trail --s3-bucket-name company-audit-logs-2026 --kms-key-id alias/audit-kms-key --is-multi-region-trail", "patterns": ["aws\\s+cloudtrail\\s+create-trail(?=.*--name\\s+company-audit-trail)(?=.*--s3-bucket-name\\s+company-audit-logs-2026)(?=.*--kms-key-id\\s+alias/audit-kms-key)(?=.*--is-multi-region-trail).*"], "explanation": "--is-multi-region-trail đảm bảo ghi nhận hoạt động API ở mọi region AWS, kể cả những region chưa dùng, giúp phát hiện sớm tài nguyên lạ bị khởi tạo trái phép."}, {"prompt": "Bật tính năng xác thực tính toàn vẹn file log (Log File Integrity Validation) cho trail company-audit-trail để kiểm toán viên có thể chứng minh log không bị sửa đổi.", "type": "command", "hint": "aws cloudtrail update-trail --name company-audit-trail --enable-log-file-validation", "patterns": ["aws\\s+cloudtrail\\s+update-trail(?=.*--name\\s+company-audit-trail)(?=.*--enable-log-file-validation).*"], "explanation": "Khi bật --enable-log-file-validation, CloudTrail tạo các digest file chứa mã băm SHA-256 định kỳ, cho phép kiểm tra bằng lệnh ''aws cloudtrail validate-logs''."}, {"prompt": "Bật dịch vụ CloudTrail bắt đầu ghi log (logging) cho trail company-audit-trail.", "type": "command", "hint": "aws cloudtrail start-logging --name company-audit-trail", "patterns": ["aws\\s+cloudtrail\\s+start-logging\\s+--name\\s+company-audit-trail"], "explanation": "Lệnh create-trail chỉ khai báo cấu hình trail, bạn bắt buộc phải gọi start-logging thì CloudTrail mới bắt đầu chuyển log vào bucket S3."}, {"prompt": "Bật CloudTrail Insights trên trail company-audit-trail để AWS AI/ML tự động phát hiện các đột biến bất thường trong lời gọi API (API call rate anomalies).", "type": "command", "hint": "aws cloudtrail put-insight-selectors --trail-name company-audit-trail --insight-selectors InsightType=ApiCallRateInsight", "patterns": ["aws\\s+cloudtrail\\s+put-insight-selectors(?=.*--trail-name\\s+company-audit-trail)(?=.*InsightType=ApiCallRateInsight).*"], "explanation": "put-insight-selectors kích hoạt mô hình máy học của AWS để tự động phát hiện các đợt gọi API tăng đột biến bất thường (như rà quét quyền IAM hoặc brute-force)."}, {"prompt": "Kiểm tra trạng thái hoạt động của trail company-audit-trail để đảm bảo IsLogging=true và ghi nhận log thành công.", "type": "command", "hint": "aws cloudtrail get-trail-status --name company-audit-trail", "patterns": ["aws\\s+cloudtrail\\s+get-trail-status\\s+--name\\s+company-audit-trail"], "explanation": "get-trail-status trả về thời gian giao log gần nhất (LatestDeliveryTime) và xác nhận trạng thái IsLogging: true."}], "reference": "## AWS CloudTrail: Audit Logging, Multi-Region & Log File Integrity\n\n**1. Vai trò cốt lõi trong Compliance (PCI-DSS & SOC 2):**\n- Ghi nhận đầy đủ: **Ai (Identity)** đã thực hiện **Lệnh gì (EventName)**, lúc **Mấy giờ (EventTime)**, từ **IP nào (SourceIPAddress)**, và kết quả thành công hay lỗi (`errorCode`/`errorMessage`).\n- Là bằng chứng kiểm toán số 1 mọi auditor luôn yêu cầu xuất trình.\n\n**2. Multi-Region Trail:**\n- Luôn luôn tạo **Multi-Region Trail** (`--is-multi-region-trail`). Khi attacker chiếm đoạt credential AWS, mục tiêu đầu tiên là launch máy ở các region lạ (vd: `eu-north-1`, `af-south-1`) để tránh bị phát hiện.\n\n**3. Log File Integrity Validation (Digest Files):**\n- Sử dụng mã băm SHA-256 và chữ ký số RSA để chứng minh tính nguyên bản của file log.\n- Xác thực nhanh bằng lệnh: `aws cloudtrail validate-logs --trail-arn <arn> --start-time <iso-date>`.\n\n**4. Bảo vệ Bucket S3 chứa Trail Logs:**\n- Bật **S3 Block Public Access** triệt để.\n- Mã hóa bằng **AWS KMS** với Customer Managed Key (CMK) có chính sách phân quyền chặt chẽ.\n- Cấm hành vi `s3:DeleteObject` trên bucket thông qua IAM Policy và Bucket Policy (hoặc dùng **S3 Object Lock - WORM compliance mode**)."}'::jsonb)
) AS l(front, payload)
JOIN decks d ON d.slug = 'labs' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT (deck_id, kind, lower(front)) DO UPDATE
SET payload = EXCLUDED.payload, updated_at = NOW();
